// Plain-language "what does this mean for the crew" lines for the results card.
//
// These lines add no calculation. They restate the verdict in terms of the crew, and for
// the hatch they compare the cabin pressure with NASA's published range for indefinite crew
// exposure (src/data/cabinAtmospheres.ts). Nothing here is generated by an AI, so every
// sentence can be traced to the verdict, the user's input, or a cited NASA number.

import { HABITABLE_RANGE_PSIA, kPaToPsia } from "../data/cabinAtmospheres";
import type { PartId, Verdict } from "../types";

export interface ConsequenceInput {
  partId: PartId;
  verdict: Verdict;
  // The cabin pressure the user entered, in kPa. null if there is none (the bracket).
  cabinKPa: number | null;
  // The outside pressure at the destination, in pascals.
  outsidePa: number;
  destinationName: string;
}

/** Formats a pressure in psia without false precision. */
function psiaText(psia: number): string {
  // Anything below 0.001 psia is vacuum for our purposes.
  if (psia < 0.001) return "close to zero";
  return `${psia.toFixed(psia < 1 ? 2 : 1)} psia`;
}

/** The lines to show under "What this means for the crew". */
export function crewConsequence(i: ConsequenceInput): string[] {
  const lines: string[] = [];

  // An imported part: the app does not know what the part is for, so it says only what the
  // verdict means for the part itself and leaves the rest to the engineer.
  if (i.partId === "imported") {
    if (i.verdict === "pass") {
      lines.push("The part is predicted to hold this load with the margin you asked for.");
    } else if (i.verdict === "marginal") {
      lines.push("The part is predicted to hold, but with less margin than your target.");
    } else {
      lines.push("The part is predicted to yield under this load. Do not rely on it as modeled.");
    }
    return lines;
  }

  if (i.partId === "hatch") {
    if (i.verdict === "pass") {
      lines.push("The hatch plate is predicted to hold the pressure difference with the margin you asked for.");
    } else if (i.verdict === "marginal") {
      lines.push("The hatch plate is predicted to hold, but with less margin than your target.");
    } else {
      lines.push("The hatch plate is predicted to yield under this pressure difference. A hatch that gives way lets the cabin air out.");
    }

    if (i.cabinKPa !== null && i.cabinKPa > 0) {
      const cabin = kPaToPsia(i.cabinKPa);
      const { min, max, source } = HABITABLE_RANGE_PSIA;
      const inside = cabin > min && cabin <= max;
      lines.push(
        `Your cabin pressure is ${i.cabinKPa} kPa (${cabin.toFixed(1)} psia). NASA's technical brief gives above ${min.toFixed(1)} and up to ${max.toFixed(1)} psia as the total pressure range for indefinite crew exposure, so this value is ${inside ? "inside" : "outside"} that range (${source.label}).`,
      );
      lines.push(
        `Outside on ${i.destinationName} the pressure is ${psiaText(kPaToPsia(i.outsidePa / 1000))}. If the hatch failed, the cabin would fall from ${cabin.toFixed(1)} psia toward that value, far below the ${min.toFixed(1)} psia minimum.`,
      );
    }
  } else {
    if (i.verdict === "pass") {
      lines.push("The bracket is predicted to hold the equipment with the margin you asked for.");
    } else if (i.verdict === "marginal") {
      lines.push("The bracket is predicted to hold, but with less margin than your target.");
    } else {
      lines.push("The bracket is predicted to yield under this load, so the equipment it holds could come loose.");
    }
  }

  return lines;
}
